using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long double K;
    cin >> N >> K;

    vector<long double> a(N);
    bool hasZero = false;
    for (int i = 0; i < N; ++i) {
        cin >> a[i];
        if (a[i] == 0.0L) hasZero = true;
    }

    // If there is a zero, any subarray containing it has product 0 <= K
    // (since K is non-negative), so the whole array is valid.
    if (hasZero) {
        cout << N << '\n';
        return 0;
    }

    // No zero exists. If K == 0, no positive-product subarray can satisfy.
    if (K == 0.0L) {
        cout << 0 << '\n';
        return 0;
    }

    int ans = 0;
    int r = 0;
    long double prod = 1.0L;

    for (int l = 0; l < N; ++l) {
        while (r < N && prod * a[r] <= K) {
            prod *= a[r];
            ++r;
        }

        ans = max(ans, r - l);

        if (r == l) {
            ++r;
        } else {
            prod /= a[l];
        }
    }

    cout << ans << '\n';
    return 0;
}

#include <stdio.h>
#include <math.h>

int main() {
    int n;
    double k;
    scanf("%d %lf", &n, &k);

    double a[n];
    for (int i = 0; i < n; i++) {
        scanf("%lf", &a[i]);
    }

    // Edge case: if any element is 0, product is 0 ≤ K always
    // We can handle this naturally in sliding window.

    double log_k = log(k);
    int max_len = 0;
    int left = 0;
    double current_log_prod = 0.0;

    for (int right = 0; right < n; right++) {
        if (a[right] == 0) {
            // Product becomes 0, which is ≤ K for any K >= 0
            // The whole window from left to right is valid.
            // We can take length = right - left + 1
            int len = right - left + 1;
            if (len > max_len) max_len = len;
            // Reset window to start after this zero for maximal length
            // But we can also just expand further: product stays 0 if zero inside.
            // So we can keep going without resetting left.
            // Since 0 ≤ K always, the window can always be extended to right.
            // The maximum possible length is from the first element after last reset to here.
            // We just need to keep track.
            continue;
        }

        current_log_prod += log(a[right]);

        while (current_log_prod > log_k && left <= right) {
            current_log_prod -= log(a[left]);
            left++;
        }

        int len = right - left + 1;
        if (len > max_len) max_len = len;
    }

    printf("%d\n", max_len);
    return 0;
}

