int main() {
    int n;
    double k;
    scanf("%d %lf", &n, &k);

    double *a = malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) scanf("%lf", &a[i]);

    int left = 0, best = 0;
    double prod = 1.0;
    int zero_count = 0;

    for (int right = 0; right < n; right++) {
        if (a[right] == 0.0) {
            zero_count++;
        } else {
            prod *= a[right];
        }

        // effective product: 0 if zero_count > 0, else prod
        // shrink while effective product > k
        while (zero_count == 0 && prod > k) {
            if (a[left] == 0.0) {
                zero_count--;
            } else {
                prod /= a[left];
            }
            left++;
        }

        if (right - left + 1 > best) best = right - left + 1;
    }

    printf("%d\n", best);
    free(a);
    return 0;
}

