import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        double K = Double.parseDouble(st.nextToken());

        double[] arr = new double[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            arr[i] = Double.parseDouble(st.nextToken());
        }

        double logK = Math.log(K);
        double[] logArr = new double[N];
        for (int i = 0; i < N; i++) {
            if (arr[i] == 0) {
                logArr[i] = Double.NEGATIVE_INFINITY; // product will be 0 ≤ K always
            } else {
                logArr[i] = Math.log(arr[i]);
            }
        }

        int left = 0;
        double currentSum = 0.0;
        int maxLen = 0;

        for (int right = 0; right < N; right++) {
            if (arr[right] == 0) {
                // 0 makes entire product 0, which is always ≤ K
                maxLen = Math.max(maxLen, right - left + 1);
                // Reset because any window containing 0 is valid, but we must continue
                // Actually since product becomes 0, we can extend as far as possible
                // But we need to reset sum since zeros break log sum
                // The best approach: treat zero as reset: any window containing zero is valid
                // We'll just handle specially by tracking last zero.
                currentSum = 0.0;
                left = right + 1;
                continue;
            }

            currentSum += logArr[right];

            while (currentSum > logK + 1e-12 && left <= right) {
                currentSum -= logArr[left];
                left++;
            }

            if (currentSum <= logK + 1e-12) {
                maxLen = Math.max(maxLen, right - left + 1);
            }
        }

        // Check for zeros separately: if any zero exists, the window from first zero to last zero
        // or covering zero can be longer than above logic. We'll do one simple pass:
        int lastZero = -1;
        for (int i = 0; i < N; i++) {
            if (arr[i] == 0) {
                if (lastZero == -1) {
                    maxLen = Math.max(maxLen, i + 1);
                } else {
                    maxLen = Math.max(maxLen, i - lastZero);
                }
                lastZero = i;
            }
        }
        if (lastZero != -1) {
            maxLen = Math.max(maxLen, N - lastZero);
        }

        System.out.println(maxLen);
    }
}

