        double k = sc.nextDouble();
        double[] a = new double[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextDouble();

        int maxLen = 0;
        int left = 0;
        int zeroCount = 0;
        double logSum = 0;
        double logK = (k > 0) ? Math.log(k) : Double.NEGATIVE_INFINITY;

        for (int right = 0; right < n; right++) {
            if (a[right] == 0) {
                zeroCount++;
            } else {
                logSum += Math.log(a[right]);
            }

            // Shrink window if needed
            while (zeroCount == 0 && logSum > logK + 1e-9) {
                if (left > right) break;
                if (a[left] == 0) {
                    zeroCount--;
                } else {
                    logSum -= Math.log(a[left]);
                }
                left++;
            }

            // Check validity
            if (zeroCount > 0 || logSum <= logK + 1e-9) {
                maxLen = Math.max(maxLen, right - left + 1);
            }
        }

        System.out.println(maxLen);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String first = fs.next();
        if (first == null) return;
        int N = Integer.parseInt(first);
        double K = fs.nextDouble();

        double[] a = new double[N];
        boolean hasZero = false;
        for (int i = 0; i < N; i++) {
            a[i] = fs.nextDouble();
            if (a[i] == 0.0) hasZero = true;
        }

        // Any subarray containing 0 has product 0 <= K (since K is non-negative),
        // so if any zero exists, the whole array is valid.
        if (hasZero) {
            System.out.println(N);
            return;
        }

        // If K == 0 and there is no zero, no positive-product subarray can satisfy.
        if (K == 0.0) {
            System.out.println(0);
            return;
        }

        // Standard two-pointers / sliding window for positive numbers.
        int ans = 0;
        int left = 0;
        double prod = 1.0;
        final double EPS = 1e-12;

        for (int right = 0; right < N; right++) {
            prod *= a[right];

            while (left <= right && prod > K + EPS) {
                prod /= a[left++];
            }

            ans = Math.max(ans, right - left + 1);
        }

        System.out.println(ans);
    }
}
